using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Markup;using System.Windows.Media.Imaging;using System.Windows.Threading;using TrayLeaf;
class CloseWindowLayoutTests {
 static int pass,fail;static void Check(bool b,string name){Console.WriteLine((b?"PASS ":"FAIL ")+name);if(b)pass++;else fail++;}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject d) where T:DependencyObject{if(d is T)yield return (T)d;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)foreach(var x in Find<T>(VisualTreeHelper.GetChild(d,i)))yield return x;}
 static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(90)};t.Tick+=delegate{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{var type=typeof(Entry).Assembly.GetType("TrayLeaf.CloseWindowDialog");Check(type!=null,"dedicated-content-sized-close-prompt");if(type==null)return 1;
 Window owner;using(var stream=typeof(Entry).Assembly.GetManifestResourceStream("TrayLeaf.MainWindow.xaml"))owner=(Window)XamlReader.Load(stream);ThemeManager.Apply(owner,"1",0);Chrome.Decorate(owner,true);owner.ShowActivated=false;owner.Left=-10000;owner.Show();
 var build=type.GetMethod("Build",BindingFlags.Static|BindingFlags.NonPublic);for(int mode=0;mode<2;mode++)for(int scale=1;scale<=2;scale++){ThemeManager.Apply(owner,mode.ToString(),0);owner.FontSize=13*scale;var d=(Window)build.Invoke(null,new object[]{owner});d.ShowActivated=false;d.Left=-10000;d.Show();Pump();var box=Find<CheckBox>(d).Single();var buttons=Find<Button>(d).Where(x=>x.Name=="ExitChoice"||x.Name=="MinimizeChoice").ToArray();var title=Find<TextBlock>(d).Single(x=>x.Name=="ClosePromptTitle");var body=Find<TextBlock>(d).Single(x=>x.Name=="ClosePromptBody");var root=(FrameworkElement)d.Content;var labelColor=((SolidColorBrush)box.Foreground).Color;var textColor=((SolidColorBrush)owner.Resources["Text"]).Color;Check(d.SizeToContent==SizeToContent.Height&&d.ResizeMode==ResizeMode.NoResize,"compact-autoheight-"+mode+"-"+scale);Check(labelColor==textColor,"suppression-text-readable-"+mode+"-"+scale);Check(buttons.Length==2&&Math.Abs(buttons[0].TransformToAncestor(root).Transform(new Point()).Y-buttons[1].TransformToAncestor(root).Transform(new Point()).Y)<1,"buttons-share-baseline-"+mode+"-"+scale);Check(title.TransformToAncestor(root).Transform(new Point()).Y>=18&&body.TransformToAncestor(root).Transform(new Point()).Y>title.ActualHeight+18,"title-body-have-deliberate-spacing-"+mode+"-"+scale);Console.WriteLine("LAYOUT height="+d.ActualHeight+" buttons="+String.Join(";",buttons.Select(x=>x.ActualWidth+"/"+x.DesiredSize.Width+" margin="+x.Margin)));Check(buttons.All(x=>x.ActualWidth+x.Margin.Left+x.Margin.Right>=x.DesiredSize.Width-.5)&&d.ActualHeight<440*scale,"no-large-empty-bottom-or-clipped-actions-"+mode+"-"+scale);Check(d.AllowsTransparency&&((SolidColorBrush)d.Background).Color.A==0,"rounded-popup-has-transparent-backing-"+mode+"-"+scale);if(args.Length>0){Directory.CreateDirectory(args[0]);var image=new RenderTargetBitmap((int)Math.Ceiling(root.ActualWidth),(int)Math.Ceiling(root.ActualHeight),96,96,PixelFormats.Pbgra32);image.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var output=File.Create(Path.Combine(args[0],"close-dialog-"+mode+"-"+scale+".png")))png.Save(output);}d.Close();}
 foreach(string choice in new[]{"ExitChoice","MinimizeChoice","Cancel"}){var d=(Window)build.Invoke(null,new object[]{owner});d.Loaded+=delegate{d.Dispatcher.BeginInvoke(new Action(delegate{if(choice=="Cancel")d.Close();else Find<Button>(d).Single(x=>x.Name==choice).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));};d.ShowDialog();var state=d.Tag;var selected=(bool?)state.GetType().GetField("Minimize",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(state);Check(selected==(choice=="Cancel"?(bool?)null:choice=="MinimizeChoice"),"decision-"+choice);}
 owner.Close();app.Shutdown();Console.WriteLine("RESULT passed="+pass+" failed="+fail);return fail==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}
